    {
      "text": "CalcResult",
      "file": "config.json",
      "line": 1,
      "id": "files[2].ids[2].branch_of"
    },
    {
      "text": "_safe_eval",
      "file": "config.json",
      "line": 1,
      "id": "files[2].ids[3].id"
    },
    {
      "text": "function",
      "file": "config.json",
      "line": 1,
      "id": "files[2].ids[3].kind"
    },
    {
      "text": "def _safe_eval(node: ast.AST) -> float:\n    if isinstance(node, ast.Constant):\n        if isinstance(node.value, (int, float)):\n            return node.value\n        raise ValueError(f\"unsupported constant: {node.value!r}\")\n    if isinstance(node, ast.BinOp):\n        op = _OPS.get(type(node.op))\n        if op is None:\n            raise ValueError(f\"unsupported operator: {type(node.op).__name__}\")\n        return op(_safe_eval(node.left), _safe_eval(node.right))\n    if isinstance(node, ast.UnaryOp):\n        op = _OPS.get(type(node.op))\n        if op is None:\n            raise ValueError(f\"unsupported unary op: {type(node.op).__name__}\")\n        return op(_safe_eval(node.operand))\n    raise ValueError(f\"unsupported expression: {type(node).__name__}\")\n\n",
      "file": "config.json",
      "line": 1,
      "id": "files[2].ids[3].code"
    },
    {
      "text": "handler.py",
      "file": "config.json",
      "line": 1,
      "id": "files[2].ids[3].file"
    },
    {
      "text": "calculate",
      "file": "config.json",
      "line": 1,
      "id": "files[2].ids[4].id"
    },
    {
      "text": "function",
      "file": "config.json",
      "line": 1,
      "id": "files[2].ids[4].kind"
    },
    {
      "text": "def calculate(expression: str) -> CalcResult:\n    \"\"\"Evaluate a mathematical expression safely.\"\"\"\n    try:\n        tree = ast.parse(expression.strip(), mode=\"eval\")\n        result = _safe_eval(tree.body)\n        return CalcResult(expression=expression, result=float(result))\n    except Exception as e:\n        return CalcResult(expression=expression, result=0.0, error=str(e))\n\n",
      "file": "config.json",
      "line": 1,
      "id": "files[2].ids[4].code"
    },
