    },
    {
      "text": "    def to_dict(self) -> dict:\n        return {\"expression\": self.expression, \"result\": self.result, \"error\": self.error}\n\n",
      "file": "config.json",
      "line": 1,
      "id": "tree.CalcResult.children.to_dict._code"
