files[2].ids[3].code._code:
{
  "code": "def _safe_eval(node: ast.AST) -> float:
    if isinstance(node, ast.Constant):
        if isinstance(node.value, (int, float)):
            return node.value
        raise ValueError(f"unsupported constant: {node.value!r}")
    if isinstance(node, ast.BinOp):
        op = _OPS.get(type(node.op))
        if op is None:
            raise ValueError(f"unsupported operator: {type(node.op).__name__}")
        return op(_safe_eval(node.left), _safe_eval(node.right))
    if isinstance(node, ast.UnaryOp):
        op = _OPS.get(type(node.op))
        if op is None:
            raise ValueError(f"unsupported unary op: {type(node.op).__name__}")
        return op(_safe_eval(node.operand))
    raise ValueError(f"unsupported expression: {type(node).__name__}")

"
}

files[2].ids[4].code._code:
{
  "code": "def calculate(expression: str) -> CalcResult:
    """Evaluate a mathematical expression safely."""
    try:
        tree = ast.parse(expression.strip(), mode="eval")
        result = _safe_eval(tree.body)
        return CalcResult(expression=expression, result=float(result))
    except Exception as e:
        return CalcResult(expression=expression, result=0.0, error=str(e))

"
}

