    {
      "text": "class",
      "file": "config.json",
      "line": 1,
      "id": "files[2].ids[1].kind"
    },
    {
      "text": "class CalcResult:\n    expression: str\n    result: float\n    error: str = \"\"\n\n    def to_dict(self) -> dict:\n        return {\"expression\": self.expression, \"result\": self.result, \"error\": self.error}\n\n",
      "file": "config.json",
      "line": 1,
      "id": "files[2].ids[1].code"
    },
    {
      "text": "handler.py",
      "file": "config.json",
      "line": 1,
