    },
    {
      "text": "function",
      "file": "config.json",
      "line": 1,
      "id": "files[2].ids[5].kind"
    },
    {
      "text": "def record(result: CalcResult) -> None:\n    _history.append(result)\n    if len(_history) > 100:\n        _history.pop(0)\n\n",
      "file": "config.json",
      "line": 1,
      "id": "files[2].ids[5].code"
    },
